struct Object {};

std::unique_ptr<Object> ptr1(new Object);
std::unique_ptr<Object> ptr2(new Object);
std::unique_ptr<Object> ptrN(nullptr);

// Relational comparison delegates to raw pointer comparison:
// Implementation detail: operator>(a, b) relies on (a.get() > b.get())

// Checks if ptr1 manages a numerically larger memory address than ptr2
bool is_ptr1_greater = (ptr1 > ptr2);

// Comparison against nullptr is standard
bool is_not_equal = (ptr1 != ptrN);

// All standard relational operators (==, !=, <, >, <=, >=) are supported
// and implemented via corresponding raw pointer comparisons.
